// What's new in Kobble: the notes of each Kobble release, as they live on
// Kobble's GitHub releases (English, with Italian and German folded in;
// the core's release-notes.ts), read through the code host of the `code`
// slot, beside the offline copy the installed Kobble carries
// (release-notes.json, made at release), so they show without the network
// too. Reaching GitHub never holds the offline copy back.
import { compareVersions, joinReleases, notesIn, notesOfBody, RELEASE_NOTES_FILE, releaseNotesFileSchema, versionOfTag, } from "@software-factory/core";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
// The offline copy of the Kobble this server belongs to: in an installed
// package it is in its root (next to README.md), in this repository at the
// repository's root; found by walking up from where the server is. No file
// gives no releases; a file that does not read is refused.
export function offlineNotes(from) {
    let folder = from;
    while (!existsSync(join(folder, RELEASE_NOTES_FILE))) {
        const up = dirname(folder);
        if (up === folder)
            return [];
        folder = up;
    }
    return releaseNotesFileSchema.parse(JSON.parse(readFileSync(join(folder, RELEASE_NOTES_FILE), "utf8"))).releases;
}
// The published vX.Y.Z releases on the code host, with their notes; null
// when they cannot be read.
export async function hostNotes(releases) {
    if (!releases)
        return null;
    try {
        return (await releases.list()).flatMap((release) => {
            const version = versionOfTag(release.tag);
            return version && !release.draft
                ? [
                    {
                        version,
                        date: release.date.slice(0, 10) || null,
                        notes: notesOfBody(release.body),
                    },
                ]
                : [];
        });
    }
    catch {
        return null;
    }
}
export class KobbleNotes {
    // The notes GitHub gave, and the look they were read after.
    read = null;
    options;
    constructor(options) {
        this.options = options;
    }
    async view(language, release) {
        const { current } = this.options;
        let problem = false;
        let kept = [];
        try {
            kept = this.options.offline();
        }
        catch {
            problem = true;
        }
        const online = await this.online(release);
        const top = release.newest ?? current;
        const known = joinReleases(kept, online)
            .filter((one) => compareVersions(one.version, top) <= 0)
            .map((one) => ({
            version: one.version,
            date: one.date,
            changes: notesIn(one.notes, language),
        }));
        const newest = release.newest
            ? {
                version: release.newest,
                release: known.find((one) => one.version === release.newest) ?? null,
            }
            : null;
        return {
            current,
            newest,
            offline: release.offline,
            checkedAt: release.checkedAt,
            releases: known.filter((one) => one.version !== newest?.version),
            problem,
        };
    }
    // GitHub's notes, read again after each look while it can be reached.
    async online(release) {
        const fresh = this.read?.at === release.checkedAt;
        if (!release.offline && !fresh) {
            // A failed read is tried again after the next look.
            const found = await this.options.online();
            this.read = {
                at: release.checkedAt,
                releases: found ?? this.read?.releases ?? [],
            };
        }
        return this.read?.releases ?? [];
    }
}
